const listAutoPurchaseCarts = `-- name: ListAutoPurchaseCarts :many
SELECT c.id, c.user_id
FROM carts c
WHERE c.status = 'open' AND c.auto_purchase AND c.expires_at > now()
  AND EXISTS (
    SELECT 1 FROM ledger_entries e
    WHERE e.account_type = 'customer_wallet' AND e.user_id = c.user_id AND e.currency = c.currency
  )
ORDER BY c.updated_at
LIMIT $1
`

type ListAutoPurchaseCartsRow struct {
	ID     pgtype.UUID `json:"id"`
	UserID pgtype.UUID `json:"user_id"`
}

// Only carts whose customer holds wallet history are considered, so the sweep
// never re-prices a cart that cannot possibly be covered yet.
func (q *Queries) ListAutoPurchaseCarts(ctx context.Context, limit int32) ([]ListAutoPurchaseCartsRow, error) {
	rows, err := q.db.Query(ctx, listAutoPurchaseCarts, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAutoPurchaseCartsRow{}
	for rows.Next() {
		var i ListAutoPurchaseCartsRow
		if err := rows.Scan(&i.ID, &i.UserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

